# -----------------------------------------------------------------------------
# 9. BH-CORRECTED KRUSKAL-WALLIS RESULTS FOR ALL PANEL B / C FUNCTIONS
# -----------------------------------------------------------------------------
panel_B_funcs <- c(
  "photosynthetic_cyanobacteria",
  "aerobic_chemoheterotrophy",
  "photoheterotrophy",
  "predatory_or_exoparasitic",
  "nitrate_reduction"
)

panel_C_funcs <- c(
  "intracellular_parasites",
  "fermentation",
  "dark_hydrogen_oxidation",
  "nitrification",
  "manganese_oxidation",
  "aerobic_ammonia_oxidation",
  "chitinolysis",
  "methylotrophy",
  "methanol_oxidation",
  "nitrogen_fixation"
)

all_funcs <- c(panel_B_funcs, panel_C_funcs)
all_funcs <- all_funcs[all_funcs %in% rownames(faprotax_final)]

cat("\n=== BH-CORRECTED KRUSKAL-WALLIS RESULTS (Panel B + C functions) ===\n")

kw_results <- data.frame()
for(func in all_funcs) {
  func_data <- data.frame(
    Abundance   = as.numeric(faprotax_final[func, ]),
    Environment = metadata_matched$Environment
  )
  kw <- kruskal.test(Abundance ~ Environment, data = func_data)
  kw_results <- rbind(kw_results, data.frame(Function = func, p_value = kw$p.value))
}

# BH correction across these 15 pre-selected functions
kw_results$p_adj <- p.adjust(kw_results$p_value, method = "BH")

for(i in seq_len(nrow(kw_results))) {
  func  <- kw_results$Function[i]
  p_adj <- kw_results$p_adj[i]

  if(!is.na(p_adj) && p_adj < 0.05) {
    func_data <- data.frame(
      Abundance   = as.numeric(faprotax_final[func, ]),
      Environment = metadata_matched$Environment
    )
    env_medians <- func_data %>%
      dplyr::group_by(Environment) %>%
      dplyr::summarise(med = median(Abundance), .groups = "drop") %>%
      dplyr::arrange(dplyr::desc(med))
    highest <- as.character(env_medians$Environment[1])
    sig <- ifelse(p_adj < 0.001, "***", ifelse(p_adj < 0.01, "**", "*"))
    cat(sprintf("%-35s p_raw=%.4f p_adj=%.4f %s highest=%s\n",
                func, kw_results$p_value[i], p_adj, sig, highest))
  } else {
    cat(sprintf("%-35s p_raw=%.4f p_adj=%.4f ns\n",
                func, kw_results$p_value[i], p_adj))
  }
}

