    "MND1", "Nitrosomonas", "Nitrosospira"
  ),
  aerobic_ammonia_oxidation = c(
    "966-1", "Ellin6067", "MND1", "Nitrosomonas", "Nitrosospira"
  ),
  manganese_oxidation = c("Leptothrix"),
  methylotrophy       = c("Methylobacter", "Methylotenera"),
  methanol_oxidation  = c("Methylotenera"),
  chitinolysis        = c("Lysobacter"),
  nitrogen_fixation   = c("Bradyrhizobium", "Mesorhizobium", "Nostoc_PCC-73102")
)

env_map <- setNames(as.character(metadata_matched$Environment),
                    metadata_matched$Sample)

for(func in names(taxa_func_list)) {
  genera <- taxa_func_list[[func]]
  cat(sprintf("\n%s:\n", func))

  for(env in c("Desiccated", "Pond", "Lake")) {
    env_samples <- names(env_map)[env_map == env]
    env_samples <- intersect(env_samples, colnames(asv_table))
    if(length(env_samples) == 0) next

    env_asv      <- asv_table[, env_samples, drop = FALSE]
    genus_totals <- data.frame()

    for(genus in genera) {
      matching <- tax_table$taxonomy6 == genus
      if(sum(matching) > 0) {
        total <- sum(rowSums(env_asv[matching, , drop = FALSE]))
        if(total > 0) {
          genus_totals <- rbind(genus_totals, data.frame(
            Genus = genus, Reads = total
          ))
        }
      }
    }

    if(nrow(genus_totals) > 0) {
      genus_totals <- genus_totals[order(-genus_totals$Reads), ]
      genus_totals$Pct <- round(genus_totals$Reads /
                                  sum(genus_totals$Reads) * 100, 1)
      cat(sprintf("  %s:\n", env))
      for(i in seq_len(min(5, nrow(genus_totals)))) {
        cat(sprintf("    %-45s %d reads (%s%%)\n",
                    genus_totals$Genus[i],
                    genus_totals$Reads[i],
                    genus_totals$Pct[i]))
      }
    } else {
      cat(sprintf("  %s: no reads found\n", env))
    }
  }
}


# -----------------------------------------------------------------------------
# 11. TAXA DRIVING PHOTOHETEROTROPHY, PREDATORY/EXOPARASITIC ACTIVITY, AND
#     NITRATE REDUCTION -- SUPPLEMENTARY HEATMAP FIGURE
#     Uses the same genus-level read-count data computed in Section 10
#     (taxa_func_list, asv_table, tax_table, env_map), restructured into a
#     plottable data frame instead of only printing to console.
# -----------------------------------------------------------------------------
cat("\nBuilding taxa-driving-function heatmap for photoheterotrophy, ",
    "predatory_or_exoparasitic, nitrate_reduction...\n")

target_funcs <- c("photoheterotrophy", "predatory_or_exoparasitic", "nitrate_reduction")

genus_pct_data <- data.frame()

for (func in target_funcs) {
  genera <- taxa_func_list[[func]]

  for (env in c("Desiccated", "Pond", "Lake")) {
    env_samples <- names(env_map)[env_map == env]
    env_samples <- intersect(env_samples, colnames(asv_table))
    if (length(env_samples) == 0) next

    env_asv <- asv_table[, env_samples, drop = FALSE]
    genus_totals <- data.frame()

    for (genus in genera) {
      matching <- tax_table$taxonomy6 == genus
      if (sum(matching) > 0) {
        total <- sum(rowSums(env_asv[matching, , drop = FALSE]))
        if (total > 0) {
          genus_totals <- rbind(genus_totals, data.frame(Genus = genus, Reads = total))
        }
      }
    }

    if (nrow(genus_totals) > 0) {
      genus_totals$Pct <- genus_totals$Reads / sum(genus_totals$Reads) * 100
      genus_totals$Function    <- func
      genus_totals$Environment <- env
      genus_pct_data <- rbind(genus_pct_data, genus_totals)
    }
  }
}

# Fill in genus/function/environment combinations with no reads as 0, so the
# heatmap grid is complete (matching the style of the other taxa heatmaps)
all_genera_target <- sort(unique(genus_pct_data$Genus))
full_grid_target <- expand.grid(
  Genus       = all_genera_target,
  Function    = target_funcs,
  Environment = factor(env_order, levels = env_order),
  stringsAsFactors = FALSE
)

genus_pct_data <- full_grid_target %>%
  dplyr::left_join(genus_pct_data, by = c("Genus", "Function", "Environment")) %>%
  dplyr::mutate(Pct = ifelse(is.na(Pct), 0, Pct))

# ggplot's discrete y-axis places the FIRST factor level at the bottom
# and the LAST at the top -- so to render top-to-bottom as
# photoheterotrophy / predatory_or_exoparasitic / nitrate_reduction
# (matching target_funcs' own order), the factor levels must be reversed
genus_pct_data$Function    <- factor(genus_pct_data$Function, levels = rev(target_funcs))
genus_pct_data$Environment <- factor(genus_pct_data$Environment, levels = env_order)

global_max_target <- max(genus_pct_data$Pct, na.rm = TRUE)

make_target_heatmap <- function(env_name, fill_high, show_y = TRUE) {
  env_data <- genus_pct_data %>%
    dplyr::filter(Environment == env_name) %>%
    dplyr::mutate(Plot_Pct = ifelse(Pct > 0, Pct, NA))

  ggplot(env_data, aes(x = Genus, y = Function, fill = Plot_Pct)) +
    geom_tile(color = "grey85", linewidth = 0.3) +
    scale_fill_gradient(
      low      = "white",
      high     = fill_high,
      na.value = "white",
      name     = paste0(env_name, "\n% of function\nreads (genus)"),
      limits   = c(0, global_max_target)
    ) +
    theme_minimal(base_size = 10) +
    labs(title = env_name, x = NULL, y = NULL) +
    theme(
      plot.title      = element_text(hjust = 0.5, size = 11, face = "bold", color = fill_high),
      axis.text.x     = element_text(angle = 45, hjust = 1, size = 7.5, face = "bold.italic"),
      axis.text.y     = element_text(size = 8, face = "bold",
                                      color = if (show_y) "black" else "white"),
      panel.grid      = element_blank(),
      legend.position = "right"
    )
}

p_target_desic <- make_target_heatmap("Desiccated", env_colors["Desiccated"], show_y = TRUE)
p_target_pond  <- make_target_heatmap("Pond",        env_colors["Pond"],       show_y = FALSE)
p_target_lake  <- make_target_heatmap("Lake",        env_colors["Lake"],       show_y = FALSE)

plot_F_supp <- (p_target_desic | p_target_pond | p_target_lake) +
  plot_annotation(
    title   = "Taxa Driving Photoheterotrophy, Predatory/Exoparasitic Activity, and Nitrate Reduction",
    caption = "Fill = percentage of that function's total reads (within habitat) contributed by each genus  |  White = genus absent or contributed 0 reads",
    theme   = theme(
      plot.title   = element_text(face = "bold", size = 11, hjust = 0.5),
      plot.caption = element_text(size = 7, hjust = 0.5)
    )
  ) &
  theme(text = element_text(family = "sans", face = "bold"))

ggsave(
  "faprotax_photohetero_predatory_nitrate_taxa_supp_notufts.pdf",
  plot_F_supp,
  width  = 14,
  height = 6,
  dpi    = 300
)
ggsave(
  "faprotax_photohetero_predatory_nitrate_taxa_supp_notufts.jpeg",
  plot_F_supp,
  width   = 14,
  height  = 6,
  dpi     = 300,
  quality = 100
)
cat("Saved: faprotax_photohetero_predatory_nitrate_taxa_supp_notufts.pdf and .jpeg\n")
